<script setup>
import { onMounted, ref } from 'vue';
import PageHeader from '../components/PageHeader.vue';
import StatusPanel from '../components/StatusPanel.vue';
import { api, queryString } from '../lib/api';
import { formatAdminDate } from '../lib/adminDate';

const data = ref({ summary: {}, items: [], pagination: {} }); const loading = ref(true); const error = ref(''); const notice = ref(''); const status = ref('');
const money = (value, currency='INR') => new Intl.NumberFormat('en-IN', { style:'currency', currency, maximumFractionDigits:2 }).format(value || 0);
async function load() { loading.value=true; error.value=''; try { data.value = await api(`/admin/ads/billing-dashboard${queryString({ status: status.value })}`); } catch(reason){ error.value=reason.message; } finally{loading.value=false;} }
async function markPaid(campaign) { const invoice=campaign.invoices?.at(-1); if(!invoice) return; try { await api(`/admin/ads/invoices/${invoice.id}/mark-paid`, {method:'POST',body:{payment_method:'manual'}}); notice.value='Invoice paid; campaign activated.'; await load(); } catch(reason){error.value=reason.message;} }
async function setStatus(campaign,next){ if(!confirm(`Set campaign to ${next}?`)) return; try{await api(`/admin/ads/campaigns/${campaign.id}/status`,{method:'PUT',body:{status:next}});notice.value=`Campaign ${next}.`;await load();}catch(reason){error.value=reason.message;} }
onMounted(load);
</script>

<template><div class="admin-page"><PageHeader eyebrow="Advertising" title="Billing dashboard" description="Invoices, payments, campaign delivery and revenue."><RouterLink class="admin-primary" to="/ads/billing-rates">Manage rates</RouterLink></PageHeader><StatusPanel tone="success" :message="notice"/><StatusPanel tone="error" :message="error"/><section class="billing-stats"><article><span>Awaiting payment</span><b>{{ data.summary.pending_payment||0 }}</b></article><article><span>Active campaigns</span><b>{{ data.summary.active||0 }}</b></article><article><span>Total invoiced</span><b>{{ money(data.summary.invoiced) }}</b></article><article><span>Paid</span><b>{{ money(data.summary.paid) }}</b></article><article><span>Outstanding</span><b>{{ money(data.summary.outstanding) }}</b></article><article><span>Impressions</span><b>{{ data.summary.impressions||0 }}</b></article><article><span>Clicks</span><b>{{ data.summary.clicks||0 }}</b></article><article><span>Valid views</span><b>{{ data.summary.valid_views||0 }}</b></article></section><section class="admin-filter-bar"><label>Campaign status<select v-model="status" @change="load"><option value="">All</option><option value="pending_payment">Pending payment</option><option value="active">Active</option><option value="paused">Paused</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label></section><section class="admin-table-card"><div v-if="loading" class="admin-loading">Loading campaigns…</div><div v-else-if="!data.items.length" class="admin-empty">No campaigns found.</div><div v-else class="admin-table-scroll"><table><thead><tr><th>Campaign</th><th>Advertiser</th><th>Billing</th><th>Delivery</th><th>Events</th><th>Invoice</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="campaign in data.items" :key="campaign.id"><td><b>{{ campaign.name }}</b><small>{{ formatAdminDate(campaign.start_at) }} → {{ formatAdminDate(campaign.end_at) }}</small></td><td>{{ campaign.advertiser?.business_name }}<small>{{ campaign.advertiser?.phone }}</small></td><td>{{ campaign.billing_model }} · {{ money(campaign.rate,campaign.currency) }}<small>Estimate {{ money(campaign.estimated_amount,campaign.currency) }}</small></td><td>{{ campaign.consumed_quantity }} / {{ campaign.target_quantity||'duration' }}<small>Accrued {{ money(campaign.accrued_amount,campaign.currency) }}</small></td><td>{{ campaign.impressions_count||0 }} views<small>{{ campaign.clicks_count||0 }} clicks · {{ campaign.valid_views_count||0 }} valid videos</small></td><td><template v-if="campaign.invoices?.length"><b>{{ campaign.invoices.at(-1).invoice_no }}</b><small>{{ money(campaign.invoices.at(-1).total,campaign.currency) }} · {{ campaign.invoices.at(-1).status }}</small></template><span v-else>—</span></td><td><span class="admin-pill">{{ campaign.status }}</span></td><td><div class="billing-actions"><button v-if="campaign.status==='pending_payment'" class="admin-primary" @click="markPaid(campaign)">Mark paid</button><button v-if="campaign.status==='active'" class="admin-secondary" @click="setStatus(campaign,'paused')">Pause</button><button v-if="campaign.status==='paused'" class="admin-secondary" @click="setStatus(campaign,'active')">Resume</button><button v-if="!['completed','cancelled'].includes(campaign.status)" class="admin-danger" @click="setStatus(campaign,'cancelled')">Cancel</button></div></td></tr></tbody></table></div></section></div></template>

<style scoped>.billing-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:15px}.billing-stats article{padding:17px;border:1px solid var(--a-line);border-radius:14px;background:var(--a-panel)}.billing-stats span{display:block;color:var(--a-muted);font-size:10px}.billing-stats b{display:block;margin-top:10px;color:var(--a-cyan);font:750 22px 'Manrope',sans-serif}.admin-table-card td small{display:block;margin-top:5px;color:var(--a-muted);font-size:10px}.billing-actions{display:flex;flex-wrap:wrap;gap:6px}.billing-actions button{min-height:34px;padding-inline:10px;font-size:10px}@media(max-width:1000px){.billing-stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.billing-stats{grid-template-columns:1fr 1fr}.billing-stats article:last-child{grid-column:1/-1}}</style>
